using Qx.Model.Wired;

namespace Qx.Game.WiredSimulation;

public static class WiredSimulationRules
{
    private static readonly IReadOnlyDictionary<WiredFormCategory, HashSet<string>> modeled = new Dictionary<WiredFormCategory, HashSet<string>>
    {
        [WiredFormCategory.Trigger] = ["ClockReachTime", "AvatarSaysSomething", "WalksOnFurniture", "WalksOffFurniture", "TriggerOnce", "UseStuff", "TriggerPeriodically", "AvatarEntersRoom", "GameStarts", "GameEnds", "ScoreAchieved", "AvatarCaught", "PeriodicLong", "BotDestinationReached", "BotAvatarReached", "UserPerformsAction", "ReceiveSignal", "AvatarClicksFurni", "PeriodicShort", "StateChange", "ClickTile", "VariableUpdate", "AvatarLeavesRoom", "UserClicksUser", "TransactionCompleted", "TransactionFailed", "RoomInitialized", "ReceiveLinkMessage", "ReceiveLinkDataframe"],
        [WiredFormCategory.Action] = ["MoveFurniTo", "GiveReward", "ProgressAchievement", "ProgressRewardTrack", "ResetRewardTrack", "Reset", "ControlClock", "AdjustClock", "CallAnotherStack", "ToggleFurniState", "MatchSnapshot", "MoveFurni", "MoveToDirection", "Chase", "Flee", "GiveScore", "Chat", "TeleportToFurniture", "TeleportToRoom", "JoinTeam", "LeaveTeam", "GiveScoreToPredefinedTeam", "ToggleToRandomState", "KickFromRoom", "MuteUser", "BotTeleport", "BotMove", "BotFollowAvatar", "BotTalk", "BotGiveHandItem", "BotChangeFigure", "BotTalkDirectToAvtr", "SetFurniAltitude", "SendSignal", "FreezeUser", "UnfreezeUser", "RelativeFurniMove", "MoveFurniToFurni", "MoveFurniToUser", "GiveVariable", "RemoveVariable", "ChangeVariable", "MoveUser", "MoveUserToFurni", "MoveAsGroup", "Log", "GiveEffect", "PlaceFurni", "RemoveFurni", "ClickConfiguration", "GiveFurniFromChest", "GiveCurrencyFromChest", "InitiateTransaction", "CancelTransaction", "SetFurniTransparency", "SetFurniHighlight", "SendLinkMessage", "SendLinkDataframe"],
        [WiredFormCategory.Condition] = ["CanPerformMove", "ClockTimeMatches", "TriggererIsOnFurni", "FurnisHaveAvatars", "NotFurnisHaveAvatars", "StatesMatch", "TimeElapsedMore", "TimeElapsedLess", "UserCountIn", "ActorIsInTeam", "HasStackedFurnis", "StuffTypeMatches", "ActorIsGroupMember", "ActorIsWearingBadge", "ActorIsWearingEffect", "NotHasStackedFurnis", "DateRangeActive", "TimeMatches", "DateMatches", "ActorHasHanditem", "TriggererMatches", "PerformingAction", "TeamHasScore", "TeamIsWinning", "FurniHasAltitude", "UserDirection", "InputSourceQuantity", "HasVariable", "VariableValue", "VariableAge", "UserLevel", "ChestHasItems", "ChestHasItemTypes"],
        [WiredFormCategory.Selector] = ["RemoteSelector", "FurniByType", "PickedFurniture", "UsersByType", "UsersInTeam", "FurniOnFurni", "FurniFromSignal", "FurnitureInNeighborhood", "FurnitureInArea", "UsersOnFurni", "UsersPerformingAction", "UsersFromSignal", "UsersByName", "UsersInNeighborhood", "UsersInArea", "UsersWithHanditem", "UsersInGroup", "FurniWithAltitude", "FurnitureWithVariable", "UsersWithVariable"],
        [WiredFormCategory.Addon] = ["VariableAddonShare", "VariableAddonImport", "AchievementEnabler", "ConditionEvaluation", "Random", "Unseen", "ExecutionLimit", "FurniSelectorFilter", "UserSelectorFilter", "FurniVariableFilter", "UserVariableFilter", "VariableCapturer", "ExecuteInOrder", "VariableTextConverter", "VariableLevelUp", "VariableTimeUtil", "VariableLeaderboard", "VariableFxHealthPoints", "VariableFxProgressBar", "VariableFxLevellingProgress", "VariableFxStatusBar", "VariableFxBossBar", "VariableFxNumberDisplay", "MovementPhysics", "CarryUsers", "AnimationTime", "JumpStrength", "Projectile", "NoMoveAnimation", "UsernamePlaceholder", "VariablePlaceholder", "FurniNamePlaceholder", "GlobalPlaceholder", "LinkSpeaker", "ChestItemTypeScanner", "CustomContract", "VariablesWebApi"],
        [WiredFormCategory.Variable] = ["Furniture", "UserVariable", "GlobalVariable", "ContextVariable", "ReferenceVariable", "EchoVariable", "Pointer", "Quest", "QuestChain", "DailyTask"]
    };

    public static bool Supports(WiredSimulationNode node) => modeled.TryGetValue(node.Category, out var names) && names.Contains(node.Name);

    public static IReadOnlyList<WiredSimulationCoverage> Coverage() => WiredFormRegistry.Definitions.Select(definition =>
        new WiredSimulationCoverage(definition.Category, definition.Code, definition.Name,
            modeled.GetValueOrDefault(definition.Category)?.Contains(definition.Name) == true ? "partial" : "unimplemented",
            limitations(definition))).ToArray();

    private static IReadOnlyList<string> limitations(WiredFormDefinition definition)
    {
        var notes = new List<string> { "Local deterministic model; server equivalence has not been established by this implementation." };
        if (definition.Name == "MoveFurniTo") notes.Add("Mode 0 is the client No movement option and leaves furniture unchanged. Nonzero modes 2, 4 and 6 remain guarded: the inspected client serializes them, but its hotel texts do not describe their destination search or spacing semantics. No nearby-tile algorithm is invented.");
        if (definition.Name == "GiveReward") notes.Add("Legacy reward replay requires RewardOutcomes in action/recipient order. RewardIndex is zero-based in the configured reward table; null means an observed no-grant outcome. Badge and product delivery are emitted as external effects, without changing worn badges or inventing inventory items. Missing outcomes leave RewardRequested and Uncertain status. Server cooldowns, prize limits, random draws and account eligibility are not derived from unavailable external state.");
        if (definition.Name is "VariableAddonShare" or "VariableAddonImport") notes.Add("Disabled sharing switches have no simulated behavior. Enabled switches require already-resolved remote definitions, text connectors and FX in the snapshot and report Uncertain. Saving is not synchronization. The engine does not invent cross-room propagation, merge precedence or imported identities.");
        if (definition.Name is "ProgressAchievement" or "ProgressRewardTrack" or "ResetRewardTrack" or "AchievementEnabler") notes.Add("External progress projection only. Supply User.Achievements and User.RewardTracks as explicit prior observations. Achievement names match the action's selected name; Code matches the AchievementEnabler entry without ACH_WF_. Set/add operations preserve unaffected entries and resolve constant or variable operands. Track reset requires ResetValue for every observed task; no zero reset, missing progress, completion threshold or reward is invented. Projections emit progress.external_projection with Uncertain severity and do not pass as server-verified. External eligibility, awards, completion events and cross-room state remain outside this projection.");
        if (definition.Name is "Quest" or "QuestChain" or "DailyTask") notes.Add("External-progress projection only. Supply a matching numeric read-only user definition bound by DefinitionFurnitureId and explicit ObservedHolders. A holder with no stored value is known absent only when listed there; an unobserved holder stops evaluation. VariableObserved inputs replace the explicitly supplied value or absence. They create no notification unless both an observed change code and origin are supplied. Quest-code interpretation, progression, resets, rewards, cross-room propagation and server-generated notifications are not inferred or live-verified. Captured object-variable readouts populate ObservedHolders for these definitions using current account IDs.");
        if (definition.Name is "FurniWithAltitude" or "FurniHasAltitude") notes.Add("Height comparisons use altitude rounded to centimetres with half values upward, matching the native altitude variable. At an exact height of 14.125, equality matches 1413, not 1412. Six stacked USVA shelves provide an exactly representable half-centimetre boundary. Live less/equal/greater controls cover nearby thresholds and separate selector and condition witnesses; raw-height and ties-to-even comparisons disagree with those controls. Captured floating-point precision still matters at other boundaries.");
        if (definition.Name is "TeleportToFurniture" or "MoveUserToFurni" or "WalksOnFurniture" or "WalksOffFurniture") notes.Add("A classic normal or fast teleport to the same XY refreshes retained human Wired contacts against the current support. It emits only contacts that actually change; repeating it with already-current contacts emits none. A direct MoveUserToFurni transfer to the same XY leaves retained contacts unchanged. Controls use a lowered one-tile entry pad on a two-by-two stage, at the anchor and outer corner, followed by horizontal carrying. Walking or a Wired step to another stage cell also refreshes contacts. Other actor states, overlapping supports and same-XY height or posture changes need separate conformance.");
        if (definition.Name is "Reset" or "TriggerOnce" or "TriggerPeriodically" or "PeriodicShort" or "PeriodicLong") notes.Add("A recorded self-resetting circuit used a 1000ms repeater gated by elapsed timer >=2 ticks. It requested reset at 1000ms and restarted on the next tick, producing 1500ms cycles. Short and long zero ticks restarted each cycle; the coincident 1500ms one-shot did not fire. Previously queued 700ms actions survived and observed the new timer. These six nonempty output streams and two empty one-shot streams have a bounded server comparison. Simulator startup after an already-due captured reset must not schedule those timers a second time; Fork preserves that initialization state.");
        if (definition.Name is "VariableAge" or "VariableTimeUtil" or "VariableLeaderboard" or "FurniVariableFilter" or "UserVariableFilter")
            notes.Add("Object-variable readouts provide no creation or update timestamp. FromClientDisplay leaves omitted timestamps unknown; explicit zero is a known timestamp. CreationTimeKnown and UpdateTimeKnown are independent. Only the timestamp used by an age, time source, date sort or displayed date column is required. Numeric assignment establishes update time but preserves unknown creation time; a new grant or replacement establishes both.");
        if (definition.Name == "LinkSpeaker") notes.Add("Client-contract projection without live-server conformance. An explicit valid incoming Link event is observed by active Link Speaker nodes that select that endpoint. Messages and Dataframes flags are evaluated independently. A matching listener emits link_speaker with the original typed Link payload; it does not send another Link event or create a triggering user. No specific bubble text, layout, audience, hearing range or refresh timing is inferred. Only saved endpoint selection is modeled.");
        if (definition.Name == "GlobalPlaceholder") notes.Add("Client-contract projection only. Global definitions use a room-wide namespace; fixed text and explicit same-room references are evaluated from supplied nodes. Other-room references require Room.SharedPlaceholders with an explicit value. The client's shared-placeholder list contains names and room IDs, not values. Missing values, duplicate names, local/global collisions and cycles are guarded. Global namespace behavior, recursive expansion, reference refresh timing, permissions and server precedence remain unverified; no network access occurs.");
        if (definition.Name == "VariablesWebApi") notes.Add("Public API and client-contract projection; no live bulk-deletion conformance. API keys are stripped from simulation nodes, copies and snapshots and never grant access. Room.Api supplies explicit read/write permissions. BulkDelete preserves variable definitions and requires AllowMassDeletion, AllHoldersKnown, calibrated BulkDeleteNotifications and complete stores for permanent user variables. A captured add-on can additionally deny mass deletion. Missing calibration stops before mutation. Offline-user notifications, duplicate add-ons, omitted external holders and room-wide timing remain guarded; no HTTP request or key generation occurs.");
        if (definition.Name == "Pointer") notes.Add("Client-contract projection without live-server conformance. PointerAccessor names an ordinary numeric Context variable whose current value is a definition furniture ID. DefinitionFurnitureId must identify exactly one captured variable. Reads, writes, age, text and derived operands resolve against the current execution context; delayed frames and forks preserve that context. Missing values, absent or ambiguous targets, domain mismatches, cycles and context-free access are guarded. No fixed alias is inferred. Persistent displays and API profiles do not acquire a synthetic execution context; chain behavior, missing-target hotel behavior and notifications remain unverified.");
        if (definition.Name is "SendLinkMessage" or "ReceiveLinkMessage" or "SendLinkDataframe" or "ReceiveLinkDataframe") notes.Add("Client-contract projection without live-server conformance. Each endpoint requires an explicit Room.Links network binding and send/receive permissions. Sends emit Link payloads; ReceiveAt creates an explicit input for another room simulation. No network access or automatic remote routing occurs. Message text is limited to 1000 UTF-8 bytes. Dataframe row i uses furniture source slot i+1 or user slot i; endpoint selection uses furniture slot 0. Missing keys, missing source values, multiple source holders and string-to-number conversion remain guarded. Incoming text placeholders are local to each receiving trigger; numeric destinations require writable context definitions.");
        if (definition.Name == "RoomInitialized") notes.Add("Requires an explicit RoomInitialized input. Starting simulation timers and an individual avatar entering are distinct events and do not synthesize room initialization. The server's room-loading timing and any initialization context remain unverified.");
        if (definition.Name is "SetFurniTransparency" or "SetFurniHighlight") notes.Add("Client-source projection only; these restricted effects have no live-server conformance. The merged target uses furniture slot 0 or user slot 1; selected audience uses user slot 0. Visual state is per current human viewer and never changes collision or furniture state. Client fades last 500ms; pulses last 1000ms. Snapshot export and forks preserve active fades and phase. Late viewers, server audience persistence, ordinary-furniture tint rejection and concurrent server overrides remain unverified. Explicit starting Visuals are required to reproduce an existing display; missing entries use the client object's initial visual state.");
        if (definition.Name == "ToggleFurniState") notes.Add("Floor Switch 1 (wf_floor_switch1) ignores this effect in both next/previous modes, including the tested adjacent-user case. Direct furniture use can still change its state. Do not generalize this exception to untested switch types.");
        if (definition.Name == "Log") notes.Add("Room-log IDs identify entries but are not a chronological sequence and can be negative. Compare timestamps for delayed ordering; logs sharing a timestamp do not prove a total cross-stack execution order. Use observed causal state changes when such ordering affects the setup.");
        if (definition.Name is "GiveVariable" or "RemoveVariable" or "ChangeVariable") notes.Add("CanCreateAndDelete controls grants/removals separately from Writable numeric assignments. A captured presence flag can allow grants and removals while denying value writes. Granting such a flag produces -1 and ignores numeric initialization. Explicit creation/deletion denial takes precedence over value-write permission. Null presence permission retains the older Writable fallback for manually supplied snapshots.");
        if (definition.Name is "GiveVariable" or "ChangeVariable") notes.Add("Live ordinary-furniture controls cover numeric GiveVariable initialization and ChangeVariable assignment with existing and absent operands. A missing same-holder or explicitly selected single-holder operand skips that destination: it does not create a missing target or replace an existing target with zero. Same-holder reads pair each selected destination with its own operand, ignoring a different secondary selection. GiveVariable without override preserves existing destinations. Constant initialization is unaffected by the missing unused variable source. These comparisons require explicit confirmed holder values in the input snapshot; room capture alone does not include them. Other operations, domains, intrinsic or derived operands and concurrent source mutations require further conformance.");
        if (definition.Name == "VariableLeaderboard") notes.Add("Rows include only requested data fields: numeric text is empty without a value column, timestamps are zero without the respective date column, and level/text connection are null when their columns are absent. Linear level thresholds, clipping, mapped/fallback text, whitespace/empty fallback and presence-flag rows have combined live comparisons. An Epoch is unnecessary for a board with no date columns.");
        if (definition.Name == "VariableLeaderboard") notes.Add("PreviewLeaderboard projects logical rows from complete StoredVariables, including users outside the room. Presence and equality filters, constant and global operands, integer and timestamp sorting, display overrides and pagination have recorded server comparisons. Give, change and remove actions update supplied stores; departure, fork and export preserve them. An explicit Epoch converts timestamps. Display refresh timing, equal-key ordering, multi-user ordering and several level-up calculators require further conformance. Preview does not model asynchronous client refresh.");
        if (definition.Name is "GiveScore" or "GiveScoreToPredefinedTeam") notes.Add("Requires explicit Room.Game phase and current TeamScores. Only a running game awards points; a resumed clock can still belong to an ended game. Calls during Pause and user calls without team membership still consume finite Game.ScoreUses, despite awarding no points. Known history or a simulated new game start is required. Team totals clamp at zero when subtracting more than their current score; these calls still consume finite allowance. A changed points/team setting resets that action's allowance in an offline build plan; unverified configuration changes invalidate history. Cross-user sharing, individual contribution totals, upper bounds, several user recipients, bots and pets require separate conformance.");
        if (definition.Name == "ScoreAchieved") notes.Add("Each box fires once per game, shared across all teams that pass its team filter. Re-crossing a threshold does not rearm it. Failed stack conditions still consume that box's activation. A changed score or team setting rearms that box; an unchanged save preserves its fired state. A freshly rearmed box can fire on a subtraction that still leaves the total at or above its threshold. Supply Game.FiredScoreTriggers, including an empty list for known unused triggers, or simulate a fresh game Start. Unknown history is rejected rather than inferred from current scores. History survives Fork and snapshot export.");
        if (definition.Name is "ControlClock" or "GameStarts" or "GameEnds") notes.Add("The game-aware source counter is identified by Room.Game.ClockId. Start resets scores and allowance history; restarting an active game emits end then start. Pause suspends scoring without ending the game. Resume after Pause restores scoring; Resume after Stop does not start a new game. Stop and Reset preserve scores. Game metadata survives snapshot export and Fork; source-clock timing still requires its separate Clock metadata. Reset team tie order and user context on lifecycle notifications require separate conformance.");
        if (definition.Name == "LeaveTeam") notes.Add("The recorded Wired-team case removes membership during a running or paused game; after Stop or Reset it is a no-op. Team membership is independent of room-group membership. @team.type uses 4 for the tested Wired team, while JoinTeam's game_type setting uses 0.");
        if (definition.Name == "UserCountIn") notes.Add("Counts human room occupants within the inclusive minimum/maximum range. A room with one human and one bot matched count 1 before leaving and count 0 in that human's leave-trigger execution. The retained triggering actor remains readable but is excluded from population. Pet-containing rooms and other departure causes require separate conformance.");
        if (definition.Name == "KickFromRoom") notes.Add("The room owner remains in the room when targeted by a kick, including delayed effects; three live controls acknowledged the trigger without a departure. OwnerId must identify the real room owner. Ordinary guests, moderation privileges, bots, pets and kick-triggered leave callbacks require separate conformance.");
        if (definition.Name is "UsersByType" or "InputSourceQuantity") notes.Add("In a leave-trigger stack, a human-type selector excludes the departing actor, but the direct triggering-user source still has quantity one. A live matrix checked exact quantities 0, 1 and 2 before and during departure. These sources are not interchangeable. The server-supplied allowed-source list rejected Room as an InputSourceQuantity user source; use a supported selector instead.");
        if (definition.Name is "UsernamePlaceholder" or "VariablePlaceholder") notes.Add("A leave-trigger execution retains a snapshot of the departing actor for triggering-user text substitution, including delayed effects and forks. Name, @user_id and source @position.x have live comparisons. The actor remains absent from the live room and is not available as a mutation target. Other departed-user variables and selectors need separate conformance.");
        if (definition.Name == "TeleportToRoom") notes.Add("Requires one selected wf_room_linker and one eligible idle standing human. The paired inventory items refer to each other through Extra. Capture retains the counterpart ID; callers must supply its RoomId, Destination, Accessible flag and calibrated DepartureMilliseconds/EffectId in RoomLink. A verified transfer used avatar effect 234 and arrived at the counterpart tile in another owned room. The source-room simulation emits RoomTeleportStarted, then RoomTransfer and a local leave event; it does not invent the destination room's scene or entry stacks. Same-room links, access failures, repeated-transfer cooldowns, blocked destinations and other recipients remain guarded. A recent return to the source room does not establish transfer eligibility.");
        if (definition.Name is "InitiateTransaction" or "CustomContract") notes.Add("Verified scope: one upgraded unlocked credit chest, one human with known inactive trade state and one explicitly selected custom contract requesting a constant credit payment with no reward. The contract must be supplied through furniture source slot 1; merely sharing the stack does not select it. Normal, fixed and auto multipliers reproduce the offer rule tree without transferring resources. Configured multiplier is 2..500; normal offers expose multiplier 1 regardless of that inactive control. Timeout schedules cancellation reason 2; explicit cancellation is reason 3. Fork retains pending deadlines. Exporting Room alone does not retain queued timeout work. Captured static payment contracts support donation and credit-only requirements. Captured static reward contracts support one matching floor-furniture payout and report completion against the contract ID. Static trade offers support credit requirements and one reserved floor-furniture reward in normal mode. Reserved entries use lock state 2 and return to state 0 on cancellation or timeout. A normal static trade for exactly one credit and one floor-furniture reward accepts OfferTrade, AcceptTrade and ConfirmTrade inputs with the active Trade.Revision. OfferTrade supplies a normalized externally validated Credits=1 payment; this does not model wallet or inventory valuation. Acceptance changes state to 2 without moving resources. Confirm after the native three-second countdown requires known credit chest Capacity, atomically deposits the credit, removes the reserved reward and fires the completion context against the contract. Other settlement shapes, custom reward sides, furniture payments, variable amounts, several recipients and conflicting active offers remain guarded.");
        if (definition.Name == "CancelTransaction") notes.Add("One known pending chest deposit or modeled contract offer can be cancelled without transferring resources; the client receives reason 3. Specific-contract mode matches ContractId, which is the selected custom-contract add-on rather than its initiating effect. Unknown active trade state or unknown contract ID remains guarded. Coin and furniture deposit capture cover requirement types 0 and 1. Existing contract offers need explicit metadata when their identity is absent from the client trade snapshot.");
        if (definition.Name == "GiveCurrencyFromChest") notes.Add("Live controls cover one upgraded credit chest and one human recipient, constant and furniture-variable amounts, games/agency categories, all balance, locked failure 15, insufficient funds failure 6 and empty all-balance failure 10. Success withdraws the exact amount atomically and emits completion context with multiplier 1, zero deposits, zero withdrawn furniture and withdrawn coins. ChestTransfer carries the earnings category; wallet or earnings delivery is external and is not inferred. Negative or missing variable operands, other recipient types, multiple chests/users, external account limits, popup presentation and exact callback timing remain unverified.");
        if (definition.Name == "GiveFurniFromChest") notes.Add("Live controls cover one upgraded furniture chest and one human recipient, locked failure 15, insufficient balance failure 6 without partial transfer, FIFO/LIFO and all-items rewards. SourceItems in ChestTransfer identify consumed chest entries rather than predicting new inventory IDs. Completion context exposes multiplier 1, zero deposits and the actual withdrawn count. The initial chest requires explicit WiredEnabled, Locked and complete unlocked items. Random ordering, multiple chests/users, empty all-items rewards, external account restrictions, popup presentation and exact callback timing remain unverified.");
        if (definition.Name is "TransactionCompleted" or "TransactionFailed") notes.Add("Live reward controls select the initiating reward effect as the contract. Empty or unrelated picked selections do not match. Selecting a chest instead of a contract is rejected by the hotel. A picked-furniture selector may supply the contract; its selection is cached for the matching stack rather than evaluated twice. Other selector combinations and contract families require additional conformance. Explicit event inputs require FurnitureId to identify the contract.");
        if (definition.Name == "ChestItemTypeScanner") notes.Add("Live controls cover counting matching stored items across furniture chests, empty selections, visible preview entries and context availability before conditions and in delayed effects. Slot 0 supplies furniture-type prototypes; slot 1 supplies furniture chests. All-items mode requires complete contents and includes trade-reserved entries with lock state 2. Other item lock states remain guarded. Preview mode requires the actual current PreviewItems, preserving repeated types, rather than deriving a preview from inventory. Credit-chest selections are rejected by the hotel. Missing preview metadata, multiple scanners writing the same context variable, wall prototypes and concurrent preview changes need additional conformance.");
        if (definition.Category == WiredFormCategory.Trigger) notes.Add("Only explicitly supplied stimuli and supported virtual timers are generated.");
        if (definition.Name is "StateChange" or "VariableUpdate" or "ScoreAchieved") notes.Add("Injected change events are notifications only; their payload does not mutate snapshot state.");
        if (definition.Name == "UserPerformsAction") notes.Add("UserAction uses NewValue for the action code and Text for an optional sign number or 'dance N'. An optional Activity patch updates known state before dispatch; without it the event remains notification-only. Dance zero is a stop, not a dance-start trigger. No sign duration is guessed.");
        if (definition.Name is "StateChange" or "VariableUpdate" or "UserPerformsAction" or "ScoreAchieved") notes.Add("Event filtering still requires server conformance tests for all option combinations.");
        if (definition.Name.Contains("Move", StringComparison.Ordinal) || definition.Name.Contains("Teleport", StringComparison.Ordinal)) notes.Add("Movement uses snapshot geometry; full client pathfinding, animation and collision equivalence are not established.");
        if (definition.Name == "MoveUserToFurni") notes.Add("Single idle human transfers immediately to the target's walkable anchor cell, preserving base altitude and posture rules. Generic transfers also support one idle standing bot in stop-walking mode to a one-tile standing or seated destination, including open/closed gate controls and destination callbacks. A destination occupied by another bot blocks this generic transfer; unlike BotTeleport, it does not share that tile in the tested controls. Large destinations include verified two-by-three beds and two-by-one sofas in their two tested orientations, with all three walking modes and entry/exit contacts. They use the anchor rather than the center or nearest footprint cell. Sitting and lying align facing to the destination support; a later transfer to a standing surface preserves that facing. Default visual movement duration is 500 ms and is separate from logical arrival; no teleport effect is added. Direct transfers may follow classic arrival while its temporary effect still finishes. Source-exit and destination-entry events support chained transfers. Blocked targets prevent movement. Captured NextStep does not reveal a final walking destination, so active-walking transfers are rejected. Multiple users, multiple targets, pets, active or affected bots, other bot walking modes, larger bot destinations, other large furniture interaction rules and classic teleports to larger targets require separate conformance.");
        if (definition.Name == "MoveUser") notes.Add("A single idle human or idle standing bot moves one tile in direction 0..7, with destination floor and occupancy checks. Movement retains facing unless rotation is configured. Standing rotation 0..7 is absolute; 9/10 turn one step clockwise/counterclockwise. A blocked move can still rotate a standing user. Sitting suppresses rotation until a successful move makes the user stand; entering the tested chair aligns facing to its direction. Frozen users can be moved and rotated without releasing the freeze. Active walking, lying, pets and multiple-user occupancy ordering remain guarded. Bot controls cover all eight directions and fixed/cardinal/relative rotations, preserving facing when no rotation is requested. Affected, frozen, following or delivering bots and bot steps onto seated or lying destinations remain guarded.");
        if (definition.Name == "MoveAsGroup") notes.Add("Members retain relative XY offsets from the selection's minimum X/Y. One-tile, 2x1 and 2x2 members, including a rotated desk, have live movement comparisons. A single user or secondary furniture supplies the target anchor, plus configured offsets. Altitude is recomputed at each destination unless KeepAltitude is set; a blocked member can stay while other members move. No XY displacement leaves height unchanged and emits no movement animation in the tested cases. MoveThroughFurni, BlockByFurni and animation modifiers have live comparison cases. NoMoveAnimation overrides AnimationTime. Overlapping source/destination footprints have live controls with MoveThroughFurni and KeepAltitude enabled and BlockByFurni disabled, including reversed selection and rotated members. One idle standing or seated human can be carried on disjoint sources, including a 2x1 footprint. Without carrying, its old surface is reevaluated. Multiple occupants, bots on multiple selected members, pets, walking or lying users, overlapping occupied sources, projectile carrying remain guarded. Contact transitions between distinct furniture have selected live controls. Other overlapping groups and multiple targets remain guarded. Stationary and larger-footprint preflight have matching live controls.");
        if (definition.Name == "TeleportToFurniture") notes.Add("Requires explicit calibrated Room.TeleportTimings for normal and fast logical contact delays, temporary effect IDs and restoration durations. Calibrate ArrivalMilliseconds from entry/exit witnesses: the tested ordinary client position packet lagged those events by about 500 ms. A single idle human uses target walkability, then tested north/northeast/east/southeast fallback priority. Landing retains the activation-time XY if the target moves, while reading the current surface height. Direct transfer chains after arrival preserve the remaining effect lifetime. Fully blocked neighborhoods, removed destinations, overlapping classic teleports, direct transfers before arrival, active walking and effect-priority interactions remain guarded. Client transport measurements do not establish exact server timer constants.");
        if (definition.Name is "WalksOnFurniture" or "WalksOffFurniture") notes.Add("Recorded direct and classic user transfers emit source-exit and destination-entry contacts, including a seated middle stage in a transfer chain. Tested stacked surfaces resolve contact at the avatar foot or posture plane, preferring the higher-base candidate; a solid carrier can be the contacted furniture even when the avatar stands at its base. Fixed-area selectors use the trigger stack selection, including when leaving the selected area. Tied contact candidates and other selector context timing remain unverified. Intermediate contacts may occur without a separate client position packet; do not reconstruct the server event sequence from client movement packets alone.");
        if (definition.Name is "RelativeFurniMove" or "MoveAsGroup" or "MoveFurniToFurni") notes.Add("Large solid-carrier controls compare avatar support and WalksOn/WalksOff witnesses for a 2x1 desk, rotated 1x2 desk and 2x2 table. An idle standing human carried from a separate elevated helper retains at least the new carrier base altitude, including non-anchor cells, then leaves the helper contact and enters the carrier contact. KeepAltitude and larger stationary destinations have controls. CarryUsers mode 0 and no CarryUsers retain the human on the different helper. Group controls here use one moving member; multiple occupied members, crowded support ties and other untested combinations are not established by these cases.");
        if (definition.Name == "MoveFurniToFurni") notes.Add("Single-item destination transfer has live coverage for color tile, chair, closed gate and nonstackable duck. Source slots resolve independently: use Picked for primary furniture and SecondaryPicked for SecondaryFurniture. Default visual duration is 500 ms; logical arrival is immediate. Without MovementPhysics, an occupied user destination rejects the move and does not start a projectile; before/occupied/after controls cover ordinary and projectile transfers. Batch tests show that saved selection order and movement packet order do not determine execution order. Sources may choose different targets in one batch. FurnitureTransferChoices supplies one ordered source-to-target step per selected source for each ambiguous action invocation; choices select a possible branch, not the hotel's random generator. Strict mode stops before an unknown branch; permissive mode samples a seeded branch and reports Uncertain. Single-target batches have live default, MoveThroughFurni, BlockByFurni and KeepAltitude coverage. Earlier moves can change later stacking or block later sources. A transfer within the same XY leaves an already topmost item unchanged, including elevated self-targets; an item below a higher surface can rise even when it targets itself. A single idle standing or seated human has live carry/no-carry comparisons, including source overlays, elevated sources, KeepAltitude and NoMoveAnimation. MoveThroughUsers permits the tested occupied destination and its avatar receives the resulting height/posture without a walk contact. Flat-floor single transfers have 2x1, rotated 1x2 and 2x2 footprint controls, including large destinations, off-anchor blockers, higher off-anchor supports, room boundaries and partial self-overlap. Partial self-overlap preserves altitude while the moving item's old top remains highest; a higher external support raises it. Nonwalkable carriers preserve at least their new base altitude under the carried avatar, including a non-anchor cell. Larger batches, uneven floor heights, movement curves on larger transfers, multiple affected users, active bots or unverified bot carrier shapes and modifiers, pets, walking/lying users, occupied batches, projectile carrying and targets moved by other sources in a multi-target batch remain guarded.");
        if (definition.Name == "ExecuteInOrder") notes.Add("Orders effects by their furniture height. Equal-height effective actions remain ambiguous. Literal empty Picked targets make the supported per-furniture move, altitude and state actions behaviorally inert; those actions do not create an ordering conflict but still execute and count as work. Dynamic sources are never assumed empty from the current snapshot.");
        if (definition.Name is "Random" or "Unseen") notes.Add("Seeded local random selection does not predict the hotel's random generator or selection order.");
        if (definition.Name is "GiveEffect" or "Chat" or "Log") notes.Add("Produces local state/effect records; no client rendering, notification delivery or external writes.");
        if (definition.Name == "PlaceFurni") notes.Add("Furniture sources 0/1/2 provide template, custom destination and initial-value operand; user sources 0/1 provide custom destination and initial-value operand. Enabled initialization creates the destination variable without a VariableChanged event. An absent operand holder or stored value initializes it to -1; disabled initialization leaves it absent. Multiple furniture operand holders produced different selections in repeated live controls. SpawnValueChoices supplies one known furniture-source choice per action, shared by every copy across its destinations; strict runs without it stop before placement, and permissive runs sample a possible holder with an uncertainty diagnostic. Multiple user holders remain guarded; the hotel selection algorithm is not predicted.");
        if (definition.Name == "PlaceFurni") notes.Add("Primary source Snapshot (110) copies stored state, direction, position and altitude from SavedSnapshot. Picked (100) copies the live template values. Snapshot mode requires complete geometry and a saved state for stateful templates; absent state is valid for stateless furniture. SecondaryPicked (101) resolves the secondary selection; Picked (100) still refers to the primary selection even in another source slot. For settled source changes, recolor RGB remains live even in Snapshot mode: a changed template color is copied together with the saved state and geometry. Same-execution recolor publication remains unverified. Removed templates and other uncaptured template metadata require separate conformance.");
        if (definition.Name == "PlaceFurni") notes.Add("Multiple templates retain offsets from their independent minimum X, Y and Z, regardless of picked order. Each custom destination receives the complete group. On-top copies use a common base at the highest supporting surface of any group member, then retain relative heights; source-altitude copies retain each original base. A missing floor cell or nonstackable surface rejects that destination group without rejecting other valid destinations. Group supports are evaluated before its copies alter the room. Live controls cover stacked and intersecting one-tile members, equal heights, 2x1 and 2x2 templates, rotation, all altitude modes, overlapping destinations and raised supports.");
        if (definition.Name == "BotGiveHandItem") notes.Add("Bot source 0 and recipient source 1 are independent. Empty optional bot name gives directly. Named delivery briefly holds the item, gives it to the human and clears the bot hand. Distant delivery requires calibrated BotTiming.DeliveryStartOffsetMilliseconds and DeliveryArrivalMilliseconds. It walks to a nearest reachable neighboring tile; equal-cost choices require an explicit BotDeliveryChoices entry for strict replay. Moving recipients retain the original destination but still receive the item by identity; BotAvatarReached fires only if the recipient remains adjacent at handoff. Delivery state and queued handoff survive Fork. A plain room export does not carry queued work. Multiple actors, removed recipients, already-moving bots, unverified elevations and newly blocked paths still require conformance.");
        if (definition.Name is "BotTalk" or "BotTalkDirectToAvtr") notes.Add("Speech effects retain the bot speaker, talk/shout/whisper mode, configured bubble width and addressed recipient. Direct talk prefixes the recipient name; whisper does not. Missing bot or recipient sources produce no speech. Public speech records have no explicit recipient list. Local username, furniture-name and numeric variable placeholders have recorded BotTalk coverage. Client rendering, cross-client visibility, other text connectors, multiple speakers and speech-rate limits require separate conformance.");
        if (definition.Name is "UsernamePlaceholder" or "VariablePlaceholder" or "FurniNamePlaceholder") notes.Add("Local $(name) matching is exact and case-sensitive. Unknown names remain literal. Empty multiple-mode sources render an empty string; empty single-mode sources preserve the token. An absent variable on a selected holder renders null. Multiple-value order is explicitly uncertain: the same users appeared in a different order after room entry. The model renders one possible ordering without certifying it. Single mode with multiple sources is explicitly uncertain. Furniture names require localized Name metadata. Duplicate local names are rejected by configuration. Acyclic nested connector tokens resolve through local placeholders; cycles and excessive local depth are guarded. Global references and output-length behavior remain unverified.");
        if (definition.Name == "BotChangeFigure") notes.Add("Single-bot named and triggering-source controls have live coverage, including case-insensitive bot names and restoration. Malformed figures, multiple bots, mixed gender and figure normalization require separate conformance.");
        if (definition.Name is "ControlClock" or "AdjustClock" or "ClockReachTime" or "ClockTimeMatches") notes.Add("Requires explicit furniture Clock metadata and a calibrated room ClockTickOffsetMilliseconds for running clocks. Visible integer state omits half seconds and initialization history. Start restarts an initialized clock; resume preserves elapsed time; reset stops, clears and removes initialization. Reset before initialization leaves a preconfigured time unchanged. Only ticking reaches thresholds; direct adjustments do not emit ClockReached. Room/client transport latency and clock overflow are not modeled.");
        if (definition.Name == "SendSignal") notes.Add("Each emitted payload toggles the tested wf_antenna1 and wf_antenna2 visual state and emits StateChanged after Signal. Their captured intrinsic @state is zero independently of the visual state. Manual use of either antenna also emits one signal with the interacting user as triggering user and empty signal-user/furniture payloads; it toggles visual state and activates state-change receivers. Split furniture payloads activate each antenna once per payload. Wired @state writes do not toggle these antennas or emit signals; do not use them to reset antenna appearance. Cross-stack ordering of same-time signal/state callbacks remains unverified.");
        if (definition.Name == "ChangeVariable") notes.Add("Server controls for wf_antenna1 and wf_antenna2 show that @state assignments -1, 0, 1 and 2, repeated assignment 1 and increment by 1 are ignored with visual state initially 0 or 1. The native value remains zero; no StateChange or ReceiveSignal observer fires, while the following acknowledgement effect runs. Other furniture and untested native writes must not inherit this exception.");
        if (definition.Name == "PlaceFurni") notes.Add("AltitudeOffset is added in all three modes: on-top uses the highest support over the whole footprint, source mode uses the source base, and custom mode uses the custom reference base. Custom altitude still reads that reference when XY uses the source location. Each destination cell must have a stackable highest surface; the tested gate blocks even when open and even with a high altitude offset. A raised stackable tile above the gate on its own cell permits the copy; a higher tile on a neighboring cell does not. Uneven on-top floors, mixed stacking permissions at equal heights and missing or ambiguous custom altitude references remain guarded. With live template sources, a copy made immediately after source-state changes within the same execution reads the earlier source state, while variable reads see the new state. Direct and called-stack controls, including two writes across stacks, match; tested copies due at least 50ms after the write see the changed state. Different state-dependent geometries and other source-data changes need further conformance. Split-signal controls with one, two and three deliveries confirm that delayed state writes and copies sharing the same originating execution and due time still copy the pre-write state. Give the copy a strictly later due time when the changed state is required. Independent external events at the same time still require separate conformance. Copies of clocks or retained pursuit state remain guarded.");
        if (definition.Name is "GiveScore" or "GiveScoreToPredefinedTeam") notes.Add("Delayed score actions observe the game phase when the effect runs. Stop followed by Start before the due time lets the pending effect award points in the new game. Resume after Stop does not reactivate scoring. Simultaneous score/lifecycle effects and individual score contributions require separate conformance.");
        if (definition.Category == WiredFormCategory.Addon && definition.Name == "VariableTextConverter") notes.Add("Inline text_mapping is parsed for ordinary and Echo variables bound by DefinitionFurnitureId at the same tile. Echo text comes from its own connectors, independently of the source numeric value; an Echo without connectors emits the number and does not inherit source text. Compatible connectors merge their keys and fallback, replacing stale resolved metadata. Different values for the same key or fallback are guarded: observed server precedence is not explained by height, numeric ID or save order, and variable text metadata can disagree with actual output. Keys are signed 64-bit integers; CR and tabs become spaces, LF separates entries, values preserve spaces and additional equals signs, duplicates inside one connector use the last value, and exact _ defines the fallback. Invalid numeric lines are ignored. Native connector-key readouts may saturate at signed 32-bit boundaries; capture leaves those mappings unknown until the connector forms are supplied. A known empty mapping stays empty. Other indirect variables and raw surrogate/control characters without accepted resolved metadata remain guarded. Context definition forms are bound by their unique variable name and context domain even when the form omits its own variable metadata.");
        if (definition.Name == "VariableLevelUp") notes.Add("Requires the parent variable and level add-on settings. Server-derived IDs are decoded, or supply Variable.Derived for planned IDs. Linear, exponential and manual interpolated thresholds have recorded value comparisons. Experience is clipped to the final threshold, percentages truncate, and is_maxed is absent until it becomes a flag with value -1. Dense manual thresholds select the highest reached level. Empty manual maps and exponential thresholds beyond exact double integer precision remain guarded. Derived change notifications, modifier removal, additional holder domains and writes through derived outputs require further conformance.");
        if (definition.Name == "VariableTimeUtil") notes.Add("Value, creation-time and update-time sources have recorded comparisons. TimeUtilities explicitly supplies the hotel's timezone and week convention; timezone rules come from the bundled database rather than host settings. Milliseconds through hours use elapsed time; whole days, weeks and months use the local calendar since Unix epoch. Management value queries can clamp 64-bit values to signed 32-bit limits, so they do not prove the internal value. Value-source assignments preserve smaller time components. Creation/update sources are read-only, require Epoch plus known parent CreatedAt/UpdatedAt relative to virtual time, and expose index zero even with a zero component mask. Idle time does not change the timestamp. Ambiguous or skipped local times and additional derived change notifications require further conformance.");
        if (definition.Name.StartsWith("VariableFx", StringComparison.Ordinal)) notes.Add("Predicts current raw values, renderer configuration, level range metadata and eligible audiences from bound variable definitions and holder values. Per-viewer visibility follows the client change mask, strict expiry and local hover input; Room.FxPresentation preserves active windows across settled export. Initial statuses do not start a window. Segment counts and standard number-display icons have configuration comparisons. Actual frame/render animation, campaign icon availability, team-zero visibility and additional override cases require further conformance.");
        if (definition.Name is "FurnitureInNeighborhood" or "UsersInNeighborhood") notes.Add("Selected room coordinates are reference position plus each mask offset minus RootX/RootY. Positive roots therefore shift selection in the negative room-axis direction. Positive, negative and compensated roots have live furniture/user-reference comparisons; user selection includes the tested bot at the selected coordinate. Multi-tile references, rotated reference semantics and moving-reference timing need further conformance.");
        if (definition.Name is "PerformingAction" or "UsersPerformingAction" or "UserPerformsAction") notes.Add("Detailed sign filters are decimal 0..17; dance filters are 'dance N' with N=1..4. Empty filters accept any active member of the category. User.Activity keeps dancing and signing independently. SignKnown distinguishes absent from unknown; SignRemainingMilliseconds is supplied lifetime from SignObservedAt, not a built-in universal duration. An aged sign with unknown lifetime is uncertain. AvatarStatus.Sign or a missing sign fragment cannot establish current Wired sign state. Capture preserves Dance; complete @sign readouts can establish current sign state but not its remaining lifetime. Other transient action classes require explicit legacy Action assumptions or further conformance.");
        if (definition.Name == "Random") notes.Add("Selects distinct effects while preferring effects absent from the recent execution batches. If too few remain, older exclusions are relaxed before more recent ones, so the requested count is still filled up to the number of effects. Supply RandomHistory for an existing add-on; an explicit empty complete history means a known fresh add-on. Unknown earlier history stays uncertain until enough executions are known. RandomChoices supplies a selected effect order for replay; without it, an ambiguous strict run stops and a permissive run samples one admissible branch. A seed is not the hotel's random state. Snapshot and Fork retain up to 100 history batches; Fork also retains the choice cursor. The recorded multi-pick tests establish batch membership, not the server's within-batch execution order or probability distribution.");
        if (definition.Name == "CallAnotherStack") notes.Add("Called stacks bypass triggers and conditions and use selections prepared before caller effects, including delayed calls. The model uses inline immediate child actions only where no unresolved dependency is detected; this is not a universal server-order guarantee. Delayed child actions remain scheduled. References to the same stack are deduplicated. Code 36 runs only on the condition-failure branch. ExecutionLimit also applies to called stacks and shares its window with direct activations.");
        if (definition.Name == "CallAnotherStack") notes.Add("Same-time furniture state or RGB dependencies between caller writes and called writes, copy sources or local variable placeholders are uncertain. Recorded server controls contradict a universally inline child schedule. Strict runs stop with order.call_dependency before effects execute; permissive runs retain the diagnostic and cannot pass. Separating dependent writes and reads in time avoids this specific ambiguity. This check does not establish ordering for other variable kinds or effects.");
        if (definition.Name == "ExecutionLimit") notes.Add("Direct triggers and CallAnotherStack share the successful-activation window. A full successful window blocks both condition branches. While it has room, condition-failure effects use their own window and do not consume successful capacity. LimitHistory.Activations and ConditionFailures preserve these separate timestamps across export and Fork; Complete and ObservedSince describe both histories. A known fresh add-on has empty complete histories. Rejected attempts do not extend either window. Multiple limiters, configuration changes and exact boundary timing require further conformance.");
        if (definition.Name is "MatchSnapshot" or "StatesMatch" or "StateChange")
            notes.Add("Captured forms decode their stored rows into SavedSnapshot. Missing components remain null and are not replaced by current room values. Restore and comparison skip components that were not stored; a current-state trigger requires an actual stored state. Legacy full SavedFurniture rows remain supported. Configuration saves refresh the currently enabled components; ApplyWiredSnapshot restores rather than captures them.");
        if (definition.Name == "MatchSnapshot")
            notes.Add("Restoring position without a stored enabled altitude recalculates the destination support height; it does not preserve the furniture's previous floating altitude. Explicit saved altitude takes precedence. The empty-floor controls cover both tested source furniture types; stacked supports and movement modifiers require separate live conformance.");
        if (definition.Category == WiredFormCategory.Action && definition.Code is 18 or 30 or 49)
            notes.Add("Negative variants 36 (call), 37 (signal) and 50 (log) run on the condition-failure branch. Directly called stacks bypass their conditions and run the positive branch; they do not invoke negative effects.");
        if (definition.Name == "RemoteSelector") notes.Add("Combines furniture and user selections from distinct referenced stacks using union or intersection. Random stack sampling and cyclic selection dependencies are rejected; missing or empty selections remain empty. Remote-selection depth is bounded by the local simulation profile.");
        if (definition.Name == "GiveEffect") notes.Add("Nonzero priority and alternate effect types are rejected.");
        if (definition.Name is "BotMove" or "BotTeleport") notes.Add("Requires explicitly calibrated Room.BotTiming. Active movement, frozen bots, untracked effects and movement modifiers remain guarded. Timing parameters are observations, not universal server constants. Two or three idle standing bots can walk or teleport to at most the same number of one-tile standing destinations. Explicit BotMovementChoices binds ActionId to ordered BotId/TargetId steps, assigns every selected bot exactly once and covers every selected destination. Three bots using two targets therefore have a two-plus-one assignment. Saved selection order does not establish the server's order or pairing. Strict mode stops before an unknown choice; permissive sampling remains Uncertain. Choices and pending group movements survive Fork.");
        if (definition.Name == "BotTeleport") notes.Add("A two- or three-bot group can share a single destination and each bot emits its own arrival trigger. Other bots do not reject the destination at command or arrival time, even a bot currently walking through the target. Single named-bot controls confirm teleport onto an already occupied bot tile. Six additional human-occupancy controls cover an idle standing human already on the destination or moved there by MoveUserToFurni during the bot teleport. Both occupants retain that tile and the bot emits its arrival callback. Nine group controls also cover two bots arriving on an initially human-occupied target, three arriving on that target, and the human joining during a three-bot teleport. Every bot reaches the shared tile and emits its own arrival callback. All explicit orders are checked offline; this does not identify the hotel execution order. Active, seated, frozen or affected human occupants, pets and nonwalkable furniture remain guarded.");
        if (definition.Name == "BotMove") notes.Add("Two or three standing bots walking to the same initially empty target compete for it; repeated server runs had different winners. The losing bot does not fire the destination trigger. A straight approach stops before the occupied target. Four diagonal directions have live controls: a westward diagonal falls back west; an eastward diagonal falls back along its north/south component. The bot then stops, with facing updated to the fallback step. If another selected bot or an idle standing bot outside the selection occupies an intermediate next tile, the walking bot recalculates a route to its original goal and continues in that step. A bot that has completed a known teleport may still be an obstacle while its visual effect remains active. Nineteen three-bot cases match full coordinate paths and arrival markers for one, two and three goals. Nine independent-stack controls combine a delayed named BotMove with an earlier BotTeleport into its intermediate or final tile. One clock-phase race let the walker enter before the teleport; another phase required a detour. These paths and arrival markers match when the observed timing/order is supplied. Transport timestamps do not establish a universal exact clock phase. Unreachable reroutes, unselected actively navigating bots, pet blockers, active or seated human blockers, unavailable preferred fallback cells, unverified fallback heights and initially occupied destinations remain guarded. Explicit group order selects a possible winner; it does not predict live scheduling.");
        if (definition.Name == "BotMove") notes.Add("Nine human-obstruction controls cover a delayed MoveUserToFurni placing an idle standing human on the intermediate route or final goal after walking starts. The bot reroutes around the intermediate human and stops before the occupied goal, even when the room allows walking through users. The control human remains outside the route. Three additional diagonal-goal controls confirm the preferred cardinal fallback before the human-occupied goal. Three initially occupied human-goal controls start no walking at all. These controls establish standing idle humans only; moving, frozen or affected humans, pets and sitting poses remain separate cases.");
        if (definition.Name == "BotMove") notes.Add("Follows an eight-direction path with verified gate detours. The replay search uses cardinal cost 10, diagonal cost 14 and an octile estimate; equal estimated totals prefer the lower remaining estimate, then insertion order. Thirty-six historical and new control paths match; diagonal cost 15 also fits those controls, so they do not uniquely identify the server's internal weights. The previous Manhattan estimate could choose a longer path around a gate. A diagonal step requires at least one free adjoining cardinal tile. A blocked destination does not start walking. Larger mazes, height limits and unverified dynamic changes need further conformance. Walking from lying poses and to larger or lying destinations remains guarded.");
        if (definition.Name == "BotMove") notes.Add("Twelve single-bot gate controls cover a zero-height one-tile Executive gate, initially open/closed or toggled 800ms after a BotMove delayed by 400ms. Closing it reroutes the walker to the original destination; opening it retains the already chosen route in this layout. Both endpoints, every path tile, gate state and arrival markers match. Dynamic gate rerouting requires a known prior walkable state and no occupant sharing that gate tile. Nonzero-height blockers, grouped walkers, follow/delivery behavior, occupied blockers and unreachable detours remain guarded. These controls do not establish the exact event order of simultaneous state changes and movement ticks.");
        if (definition.Name == "BotMove") notes.Add("Thirty-six destination-gate controls cover four diagonal approaches and a straight northward approach. An initially closed target starts no walk, even if it opens later. If a known zero-height one-tile gate closes before the final step, a diagonal approach uses the preferred cardinal fallback and stops; a straight approach stops on the preceding tile. Westward diagonal steps prefer the horizontal component, eastward steps the vertical component. An unavailable preferred fallback remains guarded. Gate-specific reached-furniture callback timing, other straight orientations, grouped walkers, follow/delivery, occupied gates and changed heights require separate evidence.");
        if (definition.Name is "BotMove" or "BotTeleport") notes.Add("Sixteen single-bot chair controls cover walking and teleporting to a ground-level one-tile Gray Dining Chair in all four cardinal rotations. Arrival uses the chair base Z, its height as ActionHeight, Sit posture and the chair direction, with the selected furniture-arrival callback. Supply Walkable=true for a sittable chair even when CanStandOn is false. BotMove permits the seated cell only as its final step; it does not route through chairs. The chair's posture height is not a standing climb, while the verified base-height limit remains checked. Unmatched seated supports, moving or overlapping seated walking destinations, larger or lying walking targets and grouped seated walks remain guarded.");
        if (definition.Name == "BotTeleport") notes.Add("Applies its effect even without changing tiles. After a known arrival, another teleport may start while the first one's effect is still active. It schedules a new arrival without renewing that effect or adding another expiry; a later teleport after expiry opens a new effect window. Unknown effects and overlapping arrivals remain guarded. One idle bot can transfer from standing, seated or lying poses to the anchor of the tested large bed or sofa, or to a floor marker underneath either support. Arrival uses the actual top support's height, posture and facing. Returning to standing ground retains facing. Teleporting between cells of the same support emits no new WalksOnFurniture, WalksOffFurniture or BotDestinationReached callback; contact transitions use only exited and newly entered supports. Target relocation, height or stance changes and blocked destinations remain guarded. Rotation during a pending teleport requires separate conformance.");
        if (definition.Name == "BotFollowAvatar") notes.Add("User source 0 selects the bot; source 1 selects the followed user and is required for stopping too. Known single-bot/user cases include adjacent starts, delayed arrival callbacks, stopped following and continued old destinations before retargeting. BotFollowChoices supplies explicit adjacent-cell decisions for conformance replay. Without choices the engine samples a possible destination and reports Uncertain, rather than pretending to predict the hotel RNG. Step, start, refresh and retry timing use an explicit BotTiming profile. Active navigation cannot be recovered from visible positions alone; supply User.Follow only when known. Multiple actors, target changes before the first step, removed users, all-neighbor blockage, large height changes and movement modifiers still need conformance.");
        if (definition.Name is "BotMove" or "BotTeleport" or "WalksOffFurniture") notes.Add("Sixteen seated-departure controls use one bot on a one-tile chair in four rotations and a separate standing destination. Walking clears Sit and ActionHeight on departure, then faces the walking direction. Teleporting also clears the seated posture on arrival while retaining the prior facing in these controls. Separate WalksOffFurniture and destination-arrival markers confirm both contacts. BotMove requires one unambiguous matching seat, known base Z and ActionHeight, and a standing target. Its first step checks the source base rather than treating the seat's ActionHeight as a standing elevation. Overlapping seats, seated-to-seated walks, lying starts and unmatched posture metadata remain guarded.");
        if (definition.Name == "BotAvatarReached") notes.Add("Generated after a followed bot has reached the target neighborhood and the configured follow arrival delay expires. The triggering actor is the bot and Reached identifies the followed user. Plain proximity, an adjacent start, a stopped follow and an ordinary BotMove near a user do not emit the callback in the recorded cases.");
        if (definition.Name == "BotDestinationReached") notes.Add("Bot moves and teleports emit destination contact events after logical arrival, filtered by the trigger's selected furniture. Same-tile requests do not emit a new arrival. Empty selection and selector-based destinations still need live conformance.");
        if (definition.Name is "BotMove" or "BotDestinationReached") notes.Add("One-tile BotMove controls retain the goal coordinates chosen at the start when the destination furniture moves away, beyond the goal or backward onto the route, immediately or after 750ms. The bot uses current support heights along that original route. Reached-furniture callbacks use the actual support contact, including intermediate route tiles; a buried tile does not also fire. Relocating the goal onto an intermediate tile can trigger its callback there while walking continues to the original goal. Permanent target deletion, changed-in-place geometry, new route blockers and equal-height support ties still require conformance.");
        if (definition.Name is "Chase" or "Flee") notes.Add("Single-user, single-furniture pursuit within three aligned tiles is partially modeled. Orthogonally adjacent users trigger collision; movement normally stops, but MoveThroughUsers allows both Chase and Flee onto the user's tile. Flee retains its prior movement direction for diagonal or distant targets; this hidden heading must be supplied as FleeDirection or established by simulated movement. Chase choices, unknown fleeing history and obstacle detours stop strict simulation. One-tile movement-physics endpoint and altitude cases are covered; multiple targets, pets, bots, larger footprints and carrying combinations remain unverified.");
        if (definition.Name == "MoveFurniToFurni") notes.Add("Single idle standing bots have live comparisons on one-tile walkable carriers, directly on the carrier, on an elevated carrier and on a separate higher support. CarryUsers mode 0 requires direct carrier contact; mode 1 carries from the same tile. Without carrying, remaining support determines the bot height. A new floor contact emits WalksOff/WalksOn and BotDestinationReached; retaining the same carrier contact emits none of those callbacks. Default 500ms and NoMoveAnimation zero-duration avatar packets are recorded. Their source altitude follows the carrier surface even when the bot initially stands on a higher separate support. Moving, affected, frozen, following or delivering bots, larger or nonwalkable carriers, destination bots and curve or projectile modifiers remain guarded.");
        if (definition.Name == "MovementPhysics") notes.Add("Relative-movement destination blocking, user blocking and altitude retention have live matrix coverage. MoveThroughFurni permits relative movement and single-item MoveFurniToFurni onto the tested gate and nonstackable duck; BlockByFurni overrides this permission when destination furniture is present. These destination transfers skip intermediate tiles. Swept collisions for other multi-tile movement actions remain unresolved.");
        if (definition.Name is "MovementPhysics" or "CarryUsers" or "RelativeFurniMove" or "MoveAsGroup" or "MoveFurniToFurni" or "ChangeVariable") notes.Add("A 40-case bot-carry matrix covers relative movement, a one-member group, @position, @occupation and furniture transfer with CarryUsers mode 1. The tested idle standing bot starts directly on a one-tile walkable carrier or on a separate higher support. Default physics rejects a closed gate destination; MoveThroughFurni permits it, KeepAltitude retains source height, and BlockByFurni overrides the permission. Two additional @position controls without the physics add-on also reject the closed gate. Final geometry, bot and furniture movement payloads and contact witnesses are compared. Larger or solid bot carriers, multiple occupants, active bots, destination bots, projectile or curved bot carrying remain guarded.");
        if (definition.Name == "CanPerformMove") notes.Add("Preflights independent directional, relative and disjoint group effects without moving furniture or changing retained directions. A blocked member rejects the entire stack; fixed blocked turns count as feasible when they find a destination. Stacks with no movement pass. Quantifier codes 0..3 did not change the recorded directional all-movements test. Delayed movements are checked when the stack triggers; the delayed effect still uses its later geometry. State-toggle and log companion effects are covered. Disjoint 2x1/2x2 groups, rotated members, stationary groups and empty selections have live preflight comparisons. Relative and group movement check destination floor and occupancy, including MoveThroughFurni and BlockByFurni. Shared or intersecting targets, multiple actors, pets/bots, other movement types and random effect selection require separate conformance.");
        if (definition.Name == "RelativeFurniMove") notes.Add("A one-tile or two-tile fixed relative move uses destination geometry. Without MoveThroughFurni, the tested Executive Gate and nonstackable furniture block it. This is independent of gate avatar walkability. BlockByFurni wins over MoveThroughFurni; KeepAltitude selects retained Z versus destination stacking height. A target avatar also blocks relative movement unless MoveThroughUsers is enabled, even when no physics add-on exists. An allowed chair move can seat the destination avatar. A blocked effect does not cancel subsequent effects. CanPerformMove can reject the stack before any effect runs. Other classes, vertical overlaps and large footprints still require further conformance.");
        if (definition.Name == "MoveToDirection") notes.Add("One-tile furniture uses retained directions per effect and selected furniture. Supply Node.MovementDirections; an empty map represents a fresh effect. Visible rotation and manual repositioning do not reveal or reset this history. Fixed blocked turns can move in the new direction during the same activation, including repeated turns. The tested stackable crate supports a moved item; nonstackable furniture and exe_gate in either state block it. Avatar collisions stop when block_on_user is enabled; otherwise blocked-turn behavior applies. Random turns, trapped history, boundary handling, larger footprints, multiple targets and movement add-on combinations still require separate conformance.");
        if (definition.Name is "Reset" or "TimeElapsedMore" or "TimeElapsedLess" or "TriggerOnce" or "TriggerPeriodically" or "PeriodicShort" or "PeriodicLong") notes.Add("Room.Timer carries the half-second @wired_timer value, next tick offset and pending reset. A fresh Start initializes a virtual timer when metadata is absent. Reset is deferred until the next timer tick; repeaters continue on their old cadence until that boundary. The boundary restarts one-shot thresholds and emits periodic zero ticks, including short and long repeaters, while retaining already delayed effects. Live mixed controls cover 350ms, 1500ms and 5000ms intervals with 700ms delayed log effects and repeated resets; all eight output streams match counts and timer values with a 100ms timestamp tolerance. Repeated pending reset requests keep the same boundary. Encoded elapsed-time condition thresholds compare inclusively against timer ticks. Counter clocks are separate. Other clock coincidences and additional intervals still require conformance.");
        if (definition.Name == "CarryUsers") notes.Add("Direct-surface and same-tile modes have live coverage for one idle standing or seated human on disjoint group members, including both cells of a 2x1 desk and a rotated desk, and on a single chair or color tile in a furniture-to-furniture transfer. Same-tile mode can take a user off a different stationary surface; final posture and base altitude follow the destination's usable surface. Nonwalkable furniture is not a standing platform. Animation altitude uses the carrier's usable height plus the incoming posture height and can differ from final user altitude. Immediate and delayed variable reads use final altitude. CanPerformMove has separate relative-movement coverage for one seated human. Staying on the same carrier does not retrigger contact; changing the contacted furniture emits exit and entry events. A height-only fall after furniture moves away does not emit a walk event. When carrier and one stationary surface share the contact plane, the tested standing avatar changes to the stationary color tile, while a seated avatar retains its carried chair; reversed item-ID roles and repeats have live controls. More stationary ties are uncertain. Fixed-area selector triggers have group/relative controls; callback ordering with other group members and user-relative selector context need separate conformance.");
        if (definition.Name == "AnimationTime") notes.Add("Reports animation duration separately from logical endpoint changes. Intermediate render frames and animation-trigger timing are not simulated.");
        if (definition.Name == "JumpStrength") notes.Add("Projects signed curve strengths for one-tile furniture transfers, relative moves, single steps, altitude changes and stopped-walking human transfers. Zero disables the curve/jump flag. Constant values use -1000..1000; variable operands may exceed that slider range and must fit the native integer payload. NoMoveAnimation removes curve animation without preventing the logical move. Selected furniture and triggering-user variable sources have live cases. Intermediate visual frames, other walking modes, grouped/multi-tile curves, missing operands and duplicate-curve precedence need further conformance.");
        if (definition.Name == "Projectile") notes.Add("One-tile furniture transfers project the four direction systems, furniture-specific Directions, rotation offsets in supported-direction steps, signed curves, selected-axis Euclidean travel time and range-dependent animation timing. The distance-based speed reduction is capped before nonpositive tile times and applied to the extended path before splitting movement and overshoot times. Logical arrival is immediate and can differ from the visible overshoot endpoint. OvershootAnimationTime is a signed duration, with OvershootDistance retained for compatibility. A single idle human shooter faces the trajectory independently of the projectile's supported directions. Internal variables require ProjectileTiming; cell-center sampling, retained values, same-modifier replacement and multiple crossings per update have live cases. Standing human and bot contacts use the sampled height before centimetre rounding and the interval from user Z through Z+2.1; ActionHeight does not shift the tested standing, sitting and lying bounds. A walking human occupies NextStep for contact purposes when supplied, before the visible origin advances. UserHits and FurnitureHits retain one entry per contact cell, including repeated IDs. Entering an already checked cell does not retroactively add a contact. Collision-variable callbacks identify the projectile but no triggering user; they do not emit AvatarCaught in the observed cases. Moving or seated bots, pets, walking height changes, overlapping actors or furniture, ranged/accelerated internal-variable paths, mask changes on a new flight, bunny hop and other movement families still require conformance.");
        if (definition.Name == "NoMoveAnimation") notes.Add("Cancels visual interpolation for tested MoveUser, MoveUserToFurni, MoveFurniToFurni and disjoint MoveAsGroup, including one carried human, while preserving immediate logical arrival. It takes precedence over an explicit AnimationTime. A carried human in a furniture-to-furniture transfer still receives an Avatar WiredMovement payload with duration zero, IsSlide and the source/destination heights; do not equate no interpolation with no packet. Classic teleport interactions and other movement families require separate conformance.");
        if (definition.Name is "FreezeUser" or "UnfreezeUser") notes.Add("Freeze options 0..4 apply effects 218, 12, 11, 53 and 163. The recorded zero-effect baseline restores to zero on unfreeze; repeated freezes retain the original baseline. User.Freeze carries previous effect and cancel-on-teleport policy. Classic teleport clears a cancellable freeze on arrival; direct user-to-furniture transfer does not. Existing nonzero baseline effects, active walking and effect-priority changes remain guarded. Capture does not infer server freeze state from the client effect.");
        if (definition.Name == "JoinTeam") notes.Add("Only the Wired game type is modeled.");
        if (definition.Name == "TeamIsWinning") notes.Add("Requires explicit scores for all four teams. Places 0..3 follow descending score; ties preserve the previous ranking after each score change and occupy distinct places. Tied initial scores require explicit Room.TeamOrder; a unique ranking can be inferred from distinct scores. Team 0 uses the triggering user's team. Absent score/order metadata is rejected rather than invented. Other game modes and reset lifecycle rules need separate conformance.");
        if (definition.Name == "ClickConfiguration") notes.Add("Projects selected human clients' click settings and the outgoing configuration payload. The six valid option pairs match live packets. These are client hit-testing preferences, not collision or walkability changes. Bot/pet targeting and rendered hit-testing require separate conformance. Injected clicks represent already-routed server input.");
        if (definition.Name is "ActorIsGroupMember" or "UsersInGroup") notes.Add("Empty group_id requires explicit current-room GroupId metadata; other group IDs are numeric text.");
        if (definition.Name == "DateRangeActive") notes.Add("Requires explicit epoch and both timestamp bounds; open-bound decoding remains unmodeled.");
        if (definition.Name is "TimeMatches" or "DateMatches") notes.Add("Requires an explicit Epoch. Named timezones use the bundled timezone database; an empty setting requires the hotel's explicit CalendarTimezone. Enabled second, minute, hour and day ranges are inclusive and may wrap. Weekday bit zero is Monday and month bit zero is January; empty masks reject every date. Date components are combined with AND. Saved inverted year ranges are normalized by the server by raising the maximum to the minimum and are not cyclic; supply the inspected settings. DST transitions and additional timezone aliases still require live conformance.");
        if (definition.Category == WiredFormCategory.Variable) notes.Add("Variable definitions and values must be supplied explicitly. Box configuration does not generate definitions, persistence or remote storage.");
        if (definition.Name == "EchoVariable") notes.Add("Uses the supplied Reference binding on the same holder and domain. Capturing a provided Echo definition attaches its configured reference. A stored furniture variable and its Echo mirrored source changes and Wired writes in live tests; direct Inspector writes to the Echo were ignored. The current server rejects references to itself or another Echo in furniture, user and global domains with echo.self_reference, retaining the prior valid reference. Multiple Echo definitions may refer to the same ordinary variable. Furniture, user and global Echo variables without connectors emitted numbers rather than source text in the recorded cases. A furniture Echo connector and fallback remained independent when source text changed; removing that connector restored numeric output. Own connectors in other Echo domains require additional conformance. Numeric reads and writes across additional domains and persistence require separate conformance.");
        if (definition.Name == "ChestHasItems") notes.Add("Counts stored furniture entries or the known credit balance for every selected chest, then applies the configured quantifier. Completed contents are mandatory for furniture chests; unknown balances are not zero. Trade-reserved entries with lock state 2 remain included in counts. Non-chest selections, other locked entry states and variable thresholds need additional live conformance.");
        if (definition.Name == "ChestHasItemTypes") notes.Add("Primary furniture provide type references; secondary source slot 1 provides chests; operand source uses slot 2. Counts matching floor kinds across those chests for each prototype, including trade-reserved entries with lock state 2, then applies all/any. Negative quantifiers 2/3 remain guarded because live marker checks did not match ordinary boolean negation. This is not a distinct-type count.");
        if (definition.Name == "RemoveFurni") notes.Add("Accepts triggering furniture, selector output or signal payload. Saved picked targets are not an available source. Temporary furniture cannot be stored in Wired selections; use a dynamic area/type/variable selector or signal. Permanent furniture is retained.");
        if (definition.Name == "RemoveFurni") notes.Add("Human support-removal controls cover a Colour Tile, Beige Chair and 2x3 Aquamarine Double Bed at their anchor. Removing the temporary item changes sitting or lying occupants to standing and clears ActionHeight. The chair and bed keep the same base Z while losing their posture height; the standing tile occupant drops to the lower surface. No WalksOn/WalksOff callback for the permanent support fired during these removals. Separate positive controls confirmed both observers. Off-anchor bed cells, multiple occupants and different remaining supports require further conformance.");
        if (definition.Name is "RemoveFurni" or "BotMove") notes.Add("A BotMove route survives deletion of its temporary destination at 0, 750 or 2000ms and still reaches the original coordinates on the remaining support. Removing that destination at 5000ms, after arrival, lowers the standing bot to the underlying tile without another reached-furniture callback. Temporary support removal recalculates the occupant's height/posture without horizontal movement or synthetic walking events. These controls used one standing bot, a one-tile Colour Tile copy and one remaining support; larger or tied supports, other furniture postures, active walking through a removed support and permanent-target pickup require separate conformance.");
        if (definition.Name == "ChangeVariable") notes.Add("Numeric min/max codes follow the recorded live correction (40=max, 41=min). Live signed 64-bit controls cover overflow across 32/64-bit boundaries, shifts masked by 63 including negative distances, sign-extending right shift, bit count, complement and minimum-value division/modulo/absolute. Power uses integer overflow through exponent 64; larger exponents saturate according to the result sign, with zero and unit bases preserved. Negative exponents return zero except for unit bases. These power branches have recorded positive, negative, zero and boundary cases; they are not ordinary floating-point Math.Pow conversion. The 32-bit profile remains an explicit compatibility hypothesis. Native inspector values clamp to signed 32-bit bounds; use FromClientDisplay and resolve IsExact=false before numeric simulation. Packed recolorable RGB writes require Furniture.RecolorRgb and the current class-specific RecolorPalette. Out-of-palette colors remain unchanged. RGB components read from the captured color; unmodeled smart-variable writes are rejected rather than stored as ordinary variables.");
        if (definition.Name == "ChangeVariable") notes.Add("Furniture @rotation uses quarter-turn indices 0..3, not room Direction values 0,2,4,6. Known Directions determine which indices a class supports. @occupation packs X in bits 16..23, Y in bits 8..15 and that rotation index in bits 0..7. Recorded writes are atomic: an invalid rotation or footprint leaves both position and direction unchanged. Same-tile writes preserve altitude; moves use destination support. Packed movement has a default 500ms visual duration; AnimationTime, NoMoveAnimation, JumpStrength and MovementPhysics have live desk comparisons. NoMoveAnimation overrides AnimationTime. KeepAltitude preserves height; MoveThroughFurni permits the tested closed gate; BlockByFurni rejects occupied destinations. Packed rotation with affected avatars, overlapping occupied footprints, projectile modifiers, new overlaps during rotation and odd furniture directions still require conformance.");
        if (definition.Name == "ChangeVariable") notes.Add("Packed destination assignment crosses intermediate furniture in the tested long desk moves, including a closed gate with BlockByFurni enabled; this is not swept-path movement. Changing only rotation at the same position keeps altitude and has no movement animation, except NoMoveAnimation produces a zero-duration rotation update when the direction actually changes. Reassigning the same position and direction to an already topmost item produces no movement update in these controls.");
        if (definition.Name == "ChangeVariable") notes.Add("Individual @position.x and @position.y writes use the position movement path. Twenty live controls cover one idle standing bot with CarryUsers mode 1, a direct or separate higher support, default physics, MoveThroughFurni, KeepAltitude, BlockByFurni and no physics add-on. A closed gate blocks default and absent physics; MoveThroughFurni permits movement and BlockByFurni overrides it. Accepted movement recalculates destination support unless KeepAltitude is set, preserves the other coordinate, and emits matching 500ms furniture and bot movement payloads with contact transitions. Larger bot carriers, extra occupants, active bots and other modifiers require separate conformance.");
        if (definition.Name == "ChangeVariable") notes.Add("Eight same-coordinate controls cover @position.x, @position.y, @position and unchanged-rotation @occupation. An already topmost carrier stays unchanged without movement payloads. A higher overlapping surface can restack the furniture despite identical XY and rotation. The tested idle bot is carried to the new carrier surface with a 500ms animation whose source is the old carrier surface; no walk or bot-destination contact fires when XY stays unchanged. These controls have no MovementPhysics modifier; same-position rotations and other modifiers remain separate branches.");
        if (definition.Name == "ChangeVariable") notes.Add("Disjoint packed movement supports one idle standing or seated human on the tested tile, 2x1 desk and chair. CarryUsers mode 0 requires direct surface contact; mode 1 also carries a user on a separate elevated support in either desk cell. Destination support and posture are reevaluated, with a solid carrier's base as the minimum standing altitude. Without carrying, the user stays at the source and its remaining support is reevaluated. Occupied destinations need MoveThroughUsers. Separate source-exit and destination-entry witnesses, KeepAltitude and zero-duration carried-avatar updates have live controls. Multiple occupants, walking, lying, unsupported bot states and pets remain guarded. Before capturing a fixture, confirm the expected avatar stance and height as well as XY; a teleport position update may precede the sitting update.");
        if (definition.Name is "RelativeFurniMove" or "MoveAsGroup" or "ChangeVariable" or "CarryUsers" or "NoMoveAnimation") notes.Add("Relative XY movement, a single-member group, @position and @occupation have 48 live bot controls with one idle standing bot and a one-tile walkable carrier. All use destination support and default 500ms interpolation. CarryUsers mode 0 requires direct carrier contact; mode 1 includes a bot on a separate higher support at the same XY. NoMoveAnimation suppresses furniture interpolation but still sends a zero-duration carried-avatar update. Its source altitude is the carrier surface, not the bot's separate upper support. Keeping the carrier contact produces no new walk or bot-destination callback; leaving the upper support for the carrier produces exit, entry and bot-destination callbacks. Frozen, affected, following, delivering or walking bots, larger or solid carriers, destination bots, multiple-member groups and physics, curve or projectile modifiers remain outside these controls.");
        if (definition.Name is "RelativeFurniMove" or "MoveAsGroup" or "MoveFurniToFurni" or "ChangeVariable" or "CarryUsers" or "AnimationTime" or "NoMoveAnimation") notes.Add("Custom AnimationTime has 60 live bot-carry controls across relative movement, a one-member group, @position, @occupation and furniture-to-furniture transfer. Both 50ms and 2000ms propagate to furniture and carried-avatar packets; Cancel Move Animation overrides an explicit 750ms with a zero-duration avatar update and no furniture interpolation packet. Direct and separate higher supports retain the same carry-mode and contact rules. These controls cover one idle standing bot and one walkable one-tile carrier, not physics, curve or projectile modifiers or additional actor states.");
        if (definition.Name == "VariableAge") notes.Add("Compares creation or last-update time using explicit WiredSimulationValue timestamps in virtual milliseconds. Recorded missing values fail; stored furniture variable probes cover millisecond/second/minute units. Context/intrinsic ages, calendar months/years and exact threshold equality remain guarded. Supply known timestamps rather than inventing ages for a live capture.");
        if (definition.Name is "GiveVariable" or "ChangeVariable" or "VariableUpdate") notes.Add("A same-value assignment refreshes update time and emits a value-change event when the trigger includes unchanged values. GiveVariable without overwrite leaves an existing holder unchanged; overwrite recreates its timestamps and emits creation rather than change. Feedback on unchanged values can recurse and must be bounded. These event classifications have live stored-furniture-variable coverage. Read-only operands retain the departing triggering actor; ChangeVariable copied @index, @user_id and source @position.x into existing furniture variables at delays of 0, 500 and 1500ms in live tests. This does not make departed users writable or include them in room selections.");
        if (definition.Name is "SetFurniAltitude" or "ChangeVariable" or "CarryUsers") notes.Add("Twenty-four vertical controls compare SetFurniAltitude and @altitude, raising and lowering one walkable one-tile carrier with one idle bot, direct or on a separate upper support. Direct support is carried even without CarryUsers. A bot on a separate upper support is resupported without an avatar animation unless carry mode 1 selects it. Default furniture and carried-avatar animation is 500ms; height-only changes produce no walk or bot-destination contacts. A lowering animation can briefly show the bot below a remaining upper support while its server @altitude stays on that support. Timed server-variable reads, not the client position cache alone, establish logical altitude. Larger bot carriers, extra occupants, active bots and additional movement modifiers require separate controls.");
        if (definition.Name is "SetFurniAltitude" or "ChangeVariable" or "CarryUsers" or "AnimationTime" or "JumpStrength" or "NoMoveAnimation") notes.Add("Vertical animation controls cover a single idle standing bot, a walkable one-tile carrier and CarryUsers mode 1. AnimationTime applies to both furniture and carried-avatar packets. A strength-200 JumpStrength appears as the furniture curve and the avatar jump power. NoMoveAnimation suppresses the furniture packet and sets avatar duration to zero, but retains that avatar jump power. These vertical controls do not establish horizontal bot curves, projectile carrying, multiple occupants or active bots. When a separate upper support remains, the client cache can show the lower animation destination after one second while the server altitude remains on the upper support; read server variables independently.");
        if (definition.Name is "RelativeFurniMove" or "MoveFurniToFurni" or "SetFurniAltitude" or "ChangeVariable" or "CarryUsers") notes.Add("Shared-carrier controls cover one idle standing human and one idle standing bot on the same one-tile walkable source, directly or on a separate upper support. Both need distinct known room indices. During height-only changes or when both remain behind, the lower-index occupant receives the support-height update; the other retains its previous logical altitude even when an animation describes another height. Replacing the bot in the room verified both index orders. Horizontal carrying relocates both occupants. A shared contact transition produces one walk-trigger context: CarrierContactChoices supplies the movement ActionId and one eligible UserId for a known branch. The chosen contact user is not determined by room-index, saved selection or movement-packet order. Missing choices remain uncertain. Bot-destination notifications are independent of the chosen walk context. More occupants, two humans, two bots, wider shared sources, active actors and physics, curve or projectile modifiers remain outside these shared-carrier controls.");
        if (definition.Name is "SetFurniAltitude" or "ChangeVariable") notes.Add("Native altitude and height values round to centimetres with half values upward: a furniture or user altitude of 4.125 reports 413. The actual geometry can retain sub-centimetre precision. SetFurniAltitude decreases and native @altitude assignments below zero clamp furniture altitude to zero in the live controls. Object-variable readouts reconcile native geometry during capture without changing the room cache; matching rounded heights preserve the more precise cached value.");
        if (definition.Name is "RelativeFurniMove" or "MoveFurniToFurni" or "MoveAsGroup" or "ChangeVariable" or "CarryUsers") notes.Add("Walkable one-by-two, two-by-one and two-by-two carriers can move one idle standing bot to a disjoint horizontal destination without changing direction. Non-anchor controls cover a stage corner and rectangular outer cells in both orientations; the bot retains its offset within the footprint. Furniture transfer, relative movement, single-member groups and packed position/occupation use the same support rules. Carry mode 0 requires direct support; mode 1 includes an upper support. Prior WiredContacts must be supplied when the preparation changed support height without a new walking contact. Larger footprints, overlap, physics, curves, projectiles and vertical movement on larger carriers require separate conformance.");
        if (definition.Name is "RelativeFurniMove" or "MoveFurniToFurni" or "MoveAsGroup" or "ChangeVariable" or "CarryUsers" or "BotTeleport" or "WalksOnFurniture" or "WalksOffFurniture" or "BotDestinationReached" or "MoveUserToFurni") notes.Add("Human and bot Wired contacts are retained event state, not just the furniture currently matching its altitude. After lowering an entry pad below a stage, the avatar can stand on the stage while retaining the pad as its previous Wired contact. Its next horizontal carry leaves the pad and enters the stage. Human controls confirm native altitude writes and the height effect, at anchor and outer cells. User.WiredContacts supplies known prior IDs; null uses the initial geometry assumption and an empty list declares no prior contacts. Supported avatar walking, teleport arrival and horizontal carrying refresh this list, while height-only carrying preserves it. Native position and altitude readouts do not reveal the list.");
        return notes;
    }
}
